import { Prism, languages, insertBefore } from '../prismCore'

var javaDocLike = languages.javadoclike = {
	'parameter': {
		pattern: /(^[\t ]*(?:\/{3}|\*|\/\*\*)\s*@(?:arg|arguments|param)\s+)\w+/m,
		lookbehind: true
	},
	'keyword': {
		// keywords are the first word in a line preceded be an `@` or surrounded by curly braces.
		// @word, {@word}
		pattern: /(^[\t ]*(?:\/{3}|\*|\/\*\*)\s*|\{)@[a-z][a-zA-Z-]+\b/m,
		lookbehind: true
	},
	'punctuation': /[{}]/
};


/**
 * Adds doc comment support to the given language and calls a given callback on each doc comment pattern.
 *
 * @param {string} lang the language add doc comment support to.
 * @param {(pattern: {inside: {rest: undefined}}) => void} callback the function called with each doc comment pattern as argument.
 */
var docCommentSupport = (lang, callback) => {
	var grammar = languages[lang];
	if (!grammar) {
		return;
	}
	var tokenName = 'doc-comment';
	var token = grammar[tokenName];

	if (!token) {
		// add doc comment: /** */
		insertBefore(lang, 'comment', token = {
			[tokenName]: {
				pattern: /\/\*\*[^/][\s\S]*?(?:\*\/|$)/,
				alias: 'comment'
			}
		});
	}

	if (token instanceof RegExp) { // convert regex to object
		token = grammar[tokenName] = { pattern: token };
	}

	if (Array.isArray(token)) {
		for (var i = 0, l = token.length; i < l; i++) {
			if (token[i] instanceof RegExp) {
				token[i] = { pattern: token[i] };
			}
			callback(token[i]);
		}
	} else {
		callback(token);
	}
}

/**
 * Adds doc-comment support to the given languages for the given documentation language.
 *
 * @param {string[]|string} languages
 * @param {Object} docLanguage
 */
var addSupport = (languages, docLanguage) => {
	(languages.map ? languages : [languages]).forEach(lang => {
		docCommentSupport(lang, pattern => {
			(pattern.inside ||= {}).rest = docLanguage;
		});
	});
}

Object.defineProperty(javaDocLike, 'addSupport', { value: addSupport });

addSupport(['java', 'javascript', 'php'], javaDocLike);
